	private static int leafFor(List<LmdbAdjacencyRunCodec.SourceSlice> leaves, long neighbor, long context) {
		int low = 0;
		int high = leaves.size() - 1;
		while (low <= high) {
			int mid = (low + high) >>> 1;
			LmdbAdjacencyRunCodec.SourceSlice leaf = leaves.get(mid);
			int cmp = LmdbAdjacencyRunCodec.comparePairsUnsigned(leaf.firstNeighbor, leaf.firstContext, neighbor,
					context);
			if (cmp <= 0) {
				low = mid + 1;
			} else {
				high = mid - 1;
			}
		}
		return Math.max(0, high);
	}

